import React from 'react';
import './Header.css';

const Header = ({ user, onSearch, onNavigate }) => {
  const handleSearch = (e) => {
    const value = e.target.value;
    const lowerValue = value.toLowerCase();

    // Filtre local de la page
    if (onSearch) onSearch(value);

    // Redirection magique en fonction des mots-clés
    if (lowerValue.includes('profil') || lowerValue.includes('krid') || (user && lowerValue.includes(user.lastName?.toLowerCase()))) {
      if (onNavigate) onNavigate('profil');
    } else if (lowerValue.includes('demande') || lowerValue.includes('trajet')) {
      if (onNavigate) onNavigate('demandes');
    } else if (lowerValue.includes('patient')) {
      if (onNavigate) onNavigate('patients');
    } else if (lowerValue.includes('entreprise') || lowerValue.includes('flotte')) {
      if (onNavigate) onNavigate('entreprise');
    } else if (lowerValue.includes('calendrier') || lowerValue.includes('planning')) {
      if (onNavigate) onNavigate('calendrier');
    } else if (lowerValue.includes('transaction') || lowerValue.includes('facture')) {
      if (onNavigate) onNavigate('transactions');
    } else if (lowerValue.includes('dashboard') || lowerValue.includes('tableau')) {
      if (onNavigate) onNavigate('dashboard');
    }
  };

  return (
    <header className="header">
      <div className="search-container">
        <div className="search-box">
          <span className="search-icon">🔍</span>
          <input
            type="text"
            placeholder="Rechercher sur cette page (ex: nom, ville)..."
            className="search-input"
            onChange={handleSearch}
          />
        </div>
      </div>

      <div className="header-actions">
        {user && (
          <div style={{ marginRight: '16px', fontWeight: '500', color: '#1e293b' }}>
            Bonjour, {user.firstName} 👋
          </div>
        )}
        <div className="notification-icon">
          🔔
          <span className="notification-badge">1</span>
        </div>
      </div>
    </header>
  );
};

export default Header;
